import Foundation
import XCTest
@testable import PAOControlKit

/// These JSON fixtures were generated by the Python host handlers using the
/// existing test-only service, verifier and interrupted-dispatch fixtures.
/// They are not screenshots, provider acceptance, or evidence of a Mac build.
final class SharedControlContractTests: XCTestCase {
    private func fixture(_ name: String) throws -> Data {
        let url = try XCTUnwrap(Bundle.module.url(
            forResource: name, withExtension: "json", subdirectory: "Fixtures/control"
        ))
        return try Data(contentsOf: url)
    }
    private func decode<T: Decodable>(_ name: String, as: T.Type = T.self) throws -> T {
        try JSONDecoder().decode(T.self, from: fixture(name))
    }
    private func envelope(_ name: String) throws -> LocalClientEnvelope<SafeTaskDetail> {
        try decode(name)
    }
    private func task(_ state: SafeTaskState, version: Int? = nil, status: String? = nil) -> TaskView {
        TaskView(taskId: state.taskId, requestId: "fixture", intent: "Fixture task",
                 state: status ?? state.state, stateVersion: version ?? state.stateVersion,
                 createdAt: "2026-10-16T00:00:00Z", updatedAt: "2026-10-16T00:00:00Z")
    }

    func testActionOrderIsApprovalBlockedRecoveryRunning() {
        XCTAssertEqual(TaskActionKind.allCases, [.approval, .blocked, .recovery, .running])
    }

    func testHostCompleteMeansReportDeliveryNotGoalCompletion() throws {
        let view = try envelope("detail_verified")
        XCTAssertEqual(view.payload.result.kind, "HOST_VERIFICATION_REPORT")
        XCTAssertEqual(view.payload.result.completeness, "COMPLETE")
        XCTAssertEqual(view.payload.result.verification.status, "VERIFIED")
        XCTAssertNil(view.payload.result.binding.resultCommit)
        XCTAssertTrue(view.payload.result.limitations.contains("HOST_REPORT_ONLY"))
        XCTAssertEqual(view.payload.result.tests.map(\.status), ["PASSED"])
        let title = try XCTUnwrap(L10n.catalogString(key: "control.result.delivery.COMPLETE", language: "en"))
        XCTAssertTrue(title.contains("report"))
        XCTAssertFalse(title.lowercased().contains("goal complete"))
    }

    func testManualContinuationReferencesSameResultAndLeavesAcceptancePending() throws {
        let view: LocalClientEnvelope<TaskContinuationPayload> = try decode("continuation_verified")
        XCTAssertTrue(view.payload.continuation.manualOnly)
        XCTAssertEqual(view.payload.result.binding, view.payload.continuation.binding)
        XCTAssertEqual(view.payload.result.resultId, view.payload.continuation.resultId)
        XCTAssertFalse(view.payload.continuation.pending.isEmpty)
        XCTAssertTrue(view.payload.continuation.text.contains(view.payload.result.resultId))
    }

    func testSameTaskNewGenerationCannotDisplayOrCopyPreviousResult() throws {
        let view: LocalClientEnvelope<TaskContinuationPayload> = try decode("continuation_verified")
        XCTAssertTrue(view.payload.matches(task(view.payload.task)))
        XCTAssertFalse(view.payload.matches(task(view.payload.task, version: view.payload.task.stateVersion + 1)))
        XCTAssertFalse(view.payload.matches(task(view.payload.task, status: "BLOCKED")))
    }

    func testRecoveryRequiresAuthoritativeCandidateNotJustBlockedState() throws {
        let view = try envelope("detail_recoverable")
        XCTAssertTrue(view.payload.recoveryStatusAvailable)
        XCTAssertNotNil(view.payload.recoveryCandidate)
        XCTAssertEqual(TaskActionKind.classify(task(view.payload.task), detail: view.payload), .recovery)
        XCTAssertEqual(TaskActionKind.classify(task(view.payload.task), detail: nil), .blocked)
        XCTAssertEqual(TaskActionKind.classify(task(view.payload.task, version: view.payload.task.stateVersion + 1),
                                              detail: view.payload), .blocked)
    }

    func testPendingApprovalTakesPriorityWithoutHidingItsTask() throws {
        let original = try JSONSerialization.jsonObject(with: fixture("detail_recoverable")) as! [String: Any]
        var payload = original["payload"] as! [String: Any]
        payload["approvals"] = [["status": "PENDING"]]
        let detail = try JSONDecoder().decode(SafeTaskDetail.self, from: JSONSerialization.data(withJSONObject: payload))
        XCTAssertEqual(TaskActionKind.classify(task(detail.task), detail: detail), .approval)
    }

    func testOldDaemonMissingRecoveryFieldIsNotAnObservedEmptyRecoveryQueue() throws {
        let original = try JSONSerialization.jsonObject(with: fixture("detail_verified")) as! [String: Any]
        var payload = original["payload"] as! [String: Any]
        payload.removeValue(forKey: "recovery_candidate")
        let detail = try JSONDecoder().decode(SafeTaskDetail.self, from: JSONSerialization.data(withJSONObject: payload))
        XCTAssertFalse(detail.recoveryStatusAvailable)
        XCTAssertNil(detail.recoveryCandidate)
    }

    func testRecoveryConfirmationFreezesCandidateAndHostIdentity() throws {
        let view = try envelope("detail_recoverable")
        let candidate = try XCTUnwrap(view.payload.recoveryCandidate)
        let request = RecoveryRequest(requestId: "recover-1", candidate: candidate,
                                      storeId: view.storeId, processEpoch: view.processEpoch)
        XCTAssertTrue(request.matches(view, task: task(view.payload.task)))
        XCTAssertFalse(request.matches(view, task: task(view.payload.task, version: candidate.taskStateVersion + 1)))
        let anotherHost = RecoveryRequest(requestId: request.requestId, candidate: candidate,
                                         storeId: String(repeating: "0", count: 32), processEpoch: view.processEpoch)
        XCTAssertFalse(anotherHost.matches(view, task: task(view.payload.task)))
        let anotherEpoch = RecoveryRequest(requestId: request.requestId, candidate: candidate,
                                          storeId: view.storeId, processEpoch: String(repeating: "0", count: 32))
        XCTAssertFalse(anotherEpoch.matches(view, task: task(view.payload.task)))
    }

    func testRecoveryStatusPreservesOriginalTupleAndCannotStartWork() throws {
        let view = try envelope("detail_recoverable")
        let request = RecoveryRequest(requestId: "recover-1", candidate: try XCTUnwrap(view.payload.recoveryCandidate),
                                      storeId: view.storeId, processEpoch: view.processEpoch)
        let body = try JSONSerialization.jsonObject(with: JSONEncoder().encode(request)) as! [String: Any]
        var statusBody = try JSONSerialization.jsonObject(with: JSONEncoder().encode(request.statusRequest)) as! [String: Any]
        XCTAssertEqual(body["operation"] as? String, "RECOVER")
        XCTAssertEqual(statusBody.removeValue(forKey: "operation") as? String, "RECOVERY_STATUS")
        var original = body
        original.removeValue(forKey: "operation")
        XCTAssertEqual(original as NSDictionary, statusBody as NSDictionary)
        XCTAssertNil(body["execution_target_id"])
        XCTAssertNil(body["authority"])
        let receipt: LocalClientEnvelope<RecoveryPayload> = try decode("recovery_receipt")
        XCTAssertFalse(receipt.payload.launchPerformed)
        XCTAssertEqual(receipt.payload.nextStep, "REVIEW_CURRENT_TASK_BEFORE_EXPLICIT_START")
    }

    func testGlobalAndProjectRevisionBindingsDecodeFromHost() throws {
        let global: SchedulingSettingsView = try decode("global_policy")
        let project: ProjectSchedulingView = try decode("project_policy")
        XCTAssertNotNil(global.revisionBinding)
        XCTAssertTrue(project.revisionBinding.isValid)
        XCTAssertEqual(project.storeId, global.storeId)
        XCTAssertEqual(project.processEpoch, global.processEpoch)
        XCTAssertEqual(project.globalRevision, global.revision)
        XCTAssertEqual(project.policySource, "GLOBAL")
        XCTAssertNil(project.schedulingPolicy)
    }

    func testOldDaemonSettingsStayReadableButCannotWriteWithoutRevision() throws {
        let old = Data(#"{"default_scheduling_policy":"BALANCED","selectable_policies":["BALANCED"]}"#.utf8)
        let settings = try JSONDecoder().decode(SchedulingSettingsView.self, from: old)
        XCTAssertNil(settings.revisionBinding)
        XCTAssertEqual(settings.defaultSchedulingPolicy, "BALANCED")
        XCTAssertFalse(PolicyRevisionBinding(revision: "", storeId: "", processEpoch: "").isValid)
    }

    func testNewControlCatalogsHaveEnglishAndChineseCoverage() {
        for key in L10n.controlKeys {
            XCTAssertNotNil(L10n.catalogString(key: key, language: "en"), key)
            XCTAssertNotNil(L10n.catalogString(key: key, language: "zh-Hans"), key)
        }
        XCTAssertEqual(L10n.controlText("result.delivery.FUTURE_STATUS"), "FUTURE_STATUS")
    }
}

@MainActor
final class SharedControlTransportTests: XCTestCase {
    private func fixture(_ name: String) throws -> String {
        let url = try XCTUnwrap(Bundle.module.url(
            forResource: name, withExtension: "json", subdirectory: "Fixtures/control"
        ))
        return try String(contentsOf: url)
    }
    private func json(_ value: String) throws -> [String: Any] {
        try XCTUnwrap(JSONSerialization.jsonObject(with: Data(value.utf8)) as? [String: Any])
    }
    private func encode(_ value: [String: Any]) throws -> String {
        String(decoding: try JSONSerialization.data(withJSONObject: value), as: UTF8.self)
    }

    func testGlobalWriteUsesReviewedRevisionAndIdentity() async throws {
        let daemon = TestDaemon()
        let body = try fixture("global_policy")
        let current = try JSONDecoder().decode(SchedulingSettingsView.self, from: Data(body.utf8))
        let binding = try XCTUnwrap(current.revisionBinding)
        var changed = try json(body)
        changed["revision"] = String(repeating: "f", count: 32)
        changed["default_scheduling_policy"] = "QUALITY_FIRST"
        daemon.route("PUT", "/v1/settings/scheduling", body: try encode(changed))
        let path = temporarySocketPath("shared-global")
        try daemon.start(socketPath: path)
        defer { daemon.stop() }
        let result = try await PAOControlClient(socketPath: path).setDefaultSchedulingPolicy(
            "QUALITY_FIRST", binding: binding
        )
        XCTAssertEqual(result.defaultSchedulingPolicy, "QUALITY_FIRST")
        let sent = try json(XCTUnwrap(daemon.receivedRequests.first?.body))
        XCTAssertEqual(sent["expected_revision"] as? String, binding.revision)
        XCTAssertEqual(sent["expected_store_id"] as? String, binding.storeId)
        XCTAssertEqual(sent["expected_process_epoch"] as? String, binding.processEpoch)
        XCTAssertNil(sent["mode"])
        XCTAssertNil(sent["authority"])
    }

    func testProjectInheritanceSendsExplicitNullAndReviewedBinding() async throws {
        let daemon = TestDaemon()
        daemon.route("PUT", "/v1/projects/project-fixture/scheduling", status: 409,
                     body: #"{"error":"policy_revision_conflict"}"#)
        let path = temporarySocketPath("shared-project")
        try daemon.start(socketPath: path)
        defer { daemon.stop() }
        let settings = try JSONDecoder().decode(ProjectSchedulingView.self,
                                                from: Data(fixture("project_policy").utf8))
        do {
            _ = try await PAOControlClient(socketPath: path).setProjectSchedulingPolicy(
                projectId: "project-fixture", schedulingPolicy: nil, binding: settings.revisionBinding
            )
            XCTFail("must preserve the server conflict")
        } catch let error as PAOClientError {
            XCTAssertEqual(error, .httpError(status: 409, code: "policy_revision_conflict"))
        }
        let sent = try json(XCTUnwrap(daemon.receivedRequests.first?.body))
        XCTAssertTrue(sent["scheduling_policy"] is NSNull)
        XCTAssertTrue(sent["manual_execution_target_id"] is NSNull)
        XCTAssertEqual(sent["expected_revision"] as? String, settings.revision)
    }

    func testPolicyConflictPreservesAuthoritativeValueAndBlocksBlindRetry() async throws {
        let daemon = TestDaemon()
        let body = try fixture("global_policy")
        daemon.route("GET", "/v1/settings/scheduling", body: body)
        daemon.route("PUT", "/v1/settings/scheduling", status: 409,
                     body: #"{"error":"policy_revision_conflict"}"#)
        let path = temporarySocketPath("shared-conflict")
        try daemon.start(socketPath: path)
        defer { daemon.stop() }
        let store = OrchestratorStore(socketPath: path, autoStartDaemon: false, autoRefresh: false)
        await store.loadSchedulingSettings()
        let snapshot = try XCTUnwrap(store.schedulingSettings)
        let first = await store.setDefaultSchedulingPolicy("QUALITY_FIRST", binding: snapshot.revisionBinding)
        XCTAssertFalse(first)
        XCTAssertTrue(store.schedulingPolicyNeedsReview)
        XCTAssertEqual(store.schedulingSettings, snapshot)
        let second = await store.setDefaultSchedulingPolicy("QUALITY_FIRST", binding: snapshot.revisionBinding)
        XCTAssertFalse(second)
        XCTAssertEqual(daemon.receivedRequests.filter { $0.method == "PUT" }.count, 1)
        XCTAssertTrue(store.schedulingPolicyError?.contains("policy_revision_conflict") == true)
    }

    func testLostOrMalformedPolicyReplyRequiresReadOnlyReviewBeforeRetry() async throws {
        let daemon = TestDaemon()
        let body = try fixture("global_policy")
        daemon.route("GET", "/v1/settings/scheduling", body: body)
        daemon.route("PUT", "/v1/settings/scheduling", body: "{}")
        let path = temporarySocketPath("shared-uncertain")
        try daemon.start(socketPath: path)
        defer { daemon.stop() }
        let store = OrchestratorStore(socketPath: path, autoStartDaemon: false, autoRefresh: false)
        await store.loadSchedulingSettings()
        let binding = store.schedulingSettings?.revisionBinding
        let saved = await store.setDefaultSchedulingPolicy("QUALITY_FIRST", binding: binding)
        XCTAssertFalse(saved)
        XCTAssertTrue(store.schedulingPolicyNeedsReview)
        await store.loadSchedulingSettings()
        // Merely observing the desired/current value never proves our write.
        XCTAssertTrue(store.schedulingPolicyNeedsReview)
        let retried = await store.setDefaultSchedulingPolicy("QUALITY_FIRST", binding: binding)
        XCTAssertFalse(retried)
        XCTAssertEqual(daemon.receivedRequests.filter { $0.method == "PUT" }.count, 1)
    }

    func testContinuationRejectsMismatchedResultBinding() async throws {
        let daemon = TestDaemon()
        var body = try json(fixture("continuation_verified"))
        var payload = body["payload"] as! [String: Any]
        var continuation = payload["continuation"] as! [String: Any]
        continuation["result_id"] = "result-other"
        payload["continuation"] = continuation
        body["payload"] = payload
        daemon.route("POST", "/v2/local-client", body: try encode(body))
        let path = temporarySocketPath("shared-binding")
        try daemon.start(socketPath: path)
        defer { daemon.stop() }
        do {
            _ = try await PAOControlClient(socketPath: path).taskContinuation("task-1", requestId: "read-1")
            XCTFail("a mismatched continuation must not be copyable")
        } catch let error as PAOClientError {
            XCTAssertEqual(error, .malformedResponse)
        }
    }

    func testRecoveryAndHistoricalStatusNeverEmitStart() async throws {
        let daemon = TestDaemon()
        let detail = try JSONDecoder().decode(LocalClientEnvelope<SafeTaskDetail>.self,
                                             from: Data(fixture("detail_recoverable").utf8))
        let request = RecoveryRequest(requestId: "recover-1", candidate: try XCTUnwrap(detail.payload.recoveryCandidate),
                                      storeId: detail.storeId, processEpoch: detail.processEpoch)
        daemon.route("POST", "/v2/local-client", body: try fixture("recovery_receipt"))
        let path = temporarySocketPath("shared-recovery")
        try daemon.start(socketPath: path)
        defer { daemon.stop() }
        let client = PAOControlClient(socketPath: path)
        let recovered = try await client.recoverTask(request)
        XCTAssertFalse(recovered.launchPerformed)
        var historical = try json(fixture("recovery_receipt"))
        historical["operation"] = "RECOVERY_STATUS"
        historical["process_epoch"] = String(repeating: "a", count: 32)
        daemon.route("POST", "/v2/local-client", body: try encode(historical), replaceExisting: true)
        let status = try await client.recoverTask(request.statusRequest)
        XCTAssertEqual(status.recovery, recovered.recovery)
        XCTAssertEqual(try daemon.receivedRequests.map { try json($0.body)["operation"] as? String },
                       ["RECOVER", "RECOVERY_STATUS"])
    }
}
